-- IEEE VHDL-93 4-Bit Combinational Ripple-Carry Adder
library ieee;
use ieee.std_logic_1164.all;

entity adder4 is
  port (
    a    : in  std_logic_vector(3 downto 0);
    b    : in  std_logic_vector(3 downto 0);
    cin  : in  std_logic;
    sum  : out std_logic_vector(3 downto 0);
    cout : out std_logic
  );
end entity adder4;

architecture rtl of adder4 is
  signal c1 : std_logic;
  signal c2 : std_logic;
  signal c3 : std_logic;
begin
  sum(0) <= a(0) xor b(0) xor cin;
  c1     <= (a(0) and b(0)) or (cin and (a(0) xor b(0)));

  sum(1) <= a(1) xor b(1) xor c1;
  c2     <= (a(1) and b(1)) or (c1 and (a(1) xor b(1)));

  sum(2) <= a(2) xor b(2) xor c2;
  c3     <= (a(2) and b(2)) or (c2 and (a(2) xor b(2)));

  sum(3) <= a(3) xor b(3) xor c3;
  cout   <= (a(3) and b(3)) or (c3 and (a(3) xor b(3)));
end architecture rtl;

-- Parameterized Synchronous Up/Down Counter with Terminal Count Flag
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity sync_updown_counter is
  generic (
    WIDTH : integer := 8
  );
  port (
    clk   : in  std_logic;
    rst   : in  std_logic;
    en    : in  std_logic;
    up    : in  std_logic;
    count : out std_logic_vector(7 downto 0);
    tc    : out std_logic
  );
end entity sync_updown_counter;

architecture rtl of sync_updown_counter is
  signal cnt_reg : std_logic_vector(7 downto 0);
  signal tc_reg  : std_logic;
begin
  p_cnt : process(clk, rst)
  begin
    if rst = '1' then
      cnt_reg <= (others => '0');
      tc_reg  <= '0';
    elsif rising_edge(clk) then
      if en = '1' then
        if up = '1' then
          if cnt_reg = X"FF" then
            cnt_reg <= X"00";
            tc_reg  <= '1';
          else
            cnt_reg <= std_logic_vector(unsigned(cnt_reg) + 1);
            tc_reg  <= '0';
          end if;
        else
          if cnt_reg = X"00" then
            cnt_reg <= X"FF";
            tc_reg  <= '1';
          else
            cnt_reg <= std_logic_vector(unsigned(cnt_reg) - 1);
            tc_reg  <= '0';
          end if;
        end if;
      else
        tc_reg <= '0';
      end if;
    end if;
  end process p_cnt;

  count <= cnt_reg;
  tc    <= tc_reg;
end architecture rtl;

-- Two-Process Moore FSM for Main/Side Street Traffic Light Controller
library ieee;
use ieee.std_logic_1164.all;

entity fsm_traffic is
  port (
    clk       : in  std_logic;
    rst       : in  std_logic;
    car_side  : in  std_logic;
    timer_exp : in  std_logic;
    main_led  : out std_logic_vector(2 downto 0);
    side_led  : out std_logic_vector(2 downto 0)
  );
end entity fsm_traffic;

architecture rtl of fsm_traffic is
  type state_t is (S_MAIN_GREEN, S_MAIN_YELLOW, S_SIDE_GREEN, S_SIDE_YELLOW);
  signal state      : state_t;
  signal next_state : state_t;
begin
  p_state_reg : process(clk, rst)
  begin
    if rst = '1' then
      state <= S_MAIN_GREEN;
    elsif rising_edge(clk) then
      state <= next_state;
    end if;
  end process p_state_reg;

  p_next_state : process(state, car_side, timer_exp)
  begin
    next_state <= state;
    main_led   <= "100";
    side_led   <= "100";
    case state is
      when S_MAIN_GREEN =>
        main_led <= "001";
        side_led <= "100";
        if car_side = '1' and timer_exp = '1' then
          next_state <= S_MAIN_YELLOW;
        end if;
      when S_MAIN_YELLOW =>
        main_led <= "010";
        side_led <= "100";
        if timer_exp = '1' then
          next_state <= S_SIDE_GREEN;
        end if;
      when S_SIDE_GREEN =>
        main_led <= "100";
        side_led <= "001";
        if timer_exp = '1' then
          next_state <= S_SIDE_YELLOW;
        end if;
      when S_SIDE_YELLOW =>
        main_led <= "100";
        side_led <= "010";
        if timer_exp = '1' then
          next_state <= S_MAIN_GREEN;
        end if;
    end case;
  end process p_next_state;
end architecture rtl;

-- Synthesizable 8N1 UART Serial Transmitter
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity uart_tx is
  generic (
    CLKS_PER_BIT : integer := 434
  );
  port (
    clk       : in  std_logic;
    rst       : in  std_logic;
    tx_start  : in  std_logic;
    tx_byte   : in  std_logic_vector(7 downto 0);
    tx_serial : out std_logic;
    tx_busy   : out std_logic
  );
end entity uart_tx;

architecture rtl of uart_tx is
  type tx_state_t is (TX_IDLE, TX_START_BIT, TX_DATA_BITS, TX_STOP_BIT);
  signal state      : tx_state_t;
  signal shift_reg  : std_logic_vector(7 downto 0);
  signal bit_idx    : integer;
  signal baud_cnt   : integer;
  signal serial_reg : std_logic;
  signal busy_reg   : std_logic;
begin
  p_uart_tx : process(clk, rst)
  begin
    if rst = '1' then
      state      <= TX_IDLE;
      shift_reg  <= (others => '0');
      bit_idx    <= 0;
      baud_cnt   <= 0;
      serial_reg <= '1';
      busy_reg   <= '0';
    elsif rising_edge(clk) then
      case state is
        when TX_IDLE =>
          serial_reg <= '1';
          busy_reg   <= '0';
          baud_cnt   <= 0;
          bit_idx    <= 0;
          if tx_start = '1' then
            shift_reg <= tx_byte;
            busy_reg  <= '1';
            state     <= TX_START_BIT;
          end if;
        when TX_START_BIT =>
          serial_reg <= '0';
          if baud_cnt = CLKS_PER_BIT - 1 then
            baud_cnt <= 0;
            state    <= TX_DATA_BITS;
          else
            baud_cnt <= baud_cnt + 1;
          end if;
        when TX_DATA_BITS =>
          serial_reg <= shift_reg(bit_idx);
          if baud_cnt = CLKS_PER_BIT - 1 then
            baud_cnt <= 0;
            if bit_idx = 7 then
              bit_idx <= 0;
              state   <= TX_STOP_BIT;
            else
              bit_idx <= bit_idx + 1;
            end if;
          else
            baud_cnt <= baud_cnt + 1;
          end if;
        when TX_STOP_BIT =>
          serial_reg <= '1';
          if baud_cnt = CLKS_PER_BIT - 1 then
            baud_cnt <= 0;
            busy_reg <= '0';
            state    <= TX_IDLE;
          else
            baud_cnt <= baud_cnt + 1;
          end if;
      end case;
    end if;
  end process p_uart_tx;

  tx_serial <= serial_reg;
  tx_busy   <= busy_reg;
end architecture rtl;

